def get_running_tasks(time, excluded_tasks=None, excluded_jobs=None):
    if excluded_tasks is None: excluded_tasks = set()
    if excluded_jobs is None: excluded_jobs = set()

    running_tasks = {m: set() for m in machine_res}
    for row in task_log_data:
        t = int(row['time'])
        task = row['task']
        event = row['event']
        machine = row['machine']

        if task in excluded_tasks: continue
        if task_res.get(task, {}).get('job') in excluded_jobs: continue

        if t < time:
            if event == 'start':
                running_tasks[machine].add(task)
            elif event == 'finish':
                running_tasks[machine].discard(task)
            elif event == 'evict':
                running_tasks[machine].discard(task)
            elif event == 'fail':
                running_tasks[machine].discard(task)
        elif t == time:
            if event == 'finish':
                running_tasks[machine].discard(task)
            elif event == 'fail':
                running_tasks[machine].discard(task)
    return running_tasks

def check_eviction(time, excluded_tasks=None, excluded_jobs=None):
    running = get_running_tasks(time, excluded_tasks, excluded_jobs)
    t092_res = task_res['T092']

    # First Fit
    for m in sorted(machine_res.keys()):
        used_cpu = sum(task_res[t]['cpu'] for t in running[m])
        used_mem = sum(task_res[t]['mem'] for t in running[m])
        if machine_res[m]['cpu'] - used_cpu >= t092_res['cpu'] and machine_res[m]['mem'] - used_mem >= t092_res['mem']:
            return f"Fits on {m} (First Fit)"

    # Preemption
    for m in sorted(machine_res.keys()):
        # Free tier tasks on this machine
        free_tier = sorted([t for t in running[m] if task_res[t]['priority'] <= 1], 
                           key=lambda t: (task_res[t]['priority'], -start_times.get(t, 0), -int(t[1:])))

        used_cpu = sum(task_res[t]['cpu'] for t in running[m])
        used_mem = sum(task_res[t]['mem'] for t in running[m])
        free_cpu = machine_res[m]['cpu'] - used_cpu
        free_mem = machine_res[m]['mem'] - used_mem

        evicted = []
        for t in free_tier:
            free_cpu += task_res[t]['cpu']
            free_mem += task_res[t]['mem']
            evicted.append(t)
            if free_cpu >= t092_res['cpu'] and free_mem >= t092_res['mem']:
                return f"Fits on {m} (Preempts {evicted})"

    return "Doesn't fit anywhere"

