def get_tasks_on_machine(machine_id, time):
    running = []
    for row in task_log:
        t = int(row['time'])
        if row['event'] == 'start' and t <= time and row['machine'] == machine_id:
            task_id = row['task']
            still_running = True
            for row2 in task_log:
                t2 = int(row2['time'])
                if row2['task'] == task_id and t2 > t:
                    if row2['event'] in ['finish', 'fail', 'evict'] and t2 <= time:
                        still_running = False
                        break
            if still_running:
                running.append(row)
    return running

